import json
h,w=17,30
G=[[0]*w for _ in range(h)]
# Each source object has the same five-row silhouette. Move its bounding-box top to row 7 (the 8 object's original top), preserving columns.
shape=[[0,1,2,3,4],[2],[1,2,3],[0,1,2,3,4],[2]]
for color,left in [(3,2),(1,9),(4,14),(8,21)]:
    for dy,offsets in enumerate(shape):
        for dx in offsets:
            G[7+dy][left+dx]=color
assert len(G)==17 and all(len(row)==30 for row in G)
assert {v for row in G for v in row}=={0,1,3,4,8}
print(json.dumps(G,separators=(',',':')))
